import{_ as t,o as a,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"performance/introduction.md","filePath":"performance/introduction.md","lastUpdated":1789464754000}'),n={name:"performance/introduction.md"};function i(s,e,c,h,d,l){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>This section sets Bagisto up for production: its caches, search, and what changes on more than one server or a long-running PHP server. The pages under <strong>Digging Deeper</strong> explain how each mechanism works. The guides here configure it, each in the same order: when you need it, the setup steps, how to test it, and what to watch.</p><h2 id="what-bagisto-does-out-of-the-box" tabindex="-1">What Bagisto Does Out of the Box <a class="header-anchor" href="#what-bagisto-does-out-of-the-box" aria-label="Permalink to &quot;What Bagisto Does Out of the Box&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Shipped default</th><th>Guide</th></tr></thead><tbody><tr><td>Full page cache</td><td>On, for guest storefront pages, stored in the <code>file</code> cache store</td><td><a href="./configure-fpc.html">Configure Full Page Cache</a></td></tr><tr><td>Application and repository cache</td><td>The <code>database</code> store; six core repositories cache their reads</td><td><a href="./../advanced/cache-strategy.html">Cache Strategy</a></td></tr><tr><td>Catalog API cache</td><td>Guest product and category API responses, for an hour</td><td><a href="./../advanced/cache-strategy.html#catalog-api-cache">Cache Strategy</a></td></tr><tr><td>Product search</td><td>The database</td><td><a href="./configure-elasticsearch.html">Configure Elasticsearch</a></td></tr><tr><td>Queue</td><td><code>sync</code> in <code>.env.example</code>: jobs run inside the request</td><td><a href="./../advanced/queue-jobs-scheduling.html">Queues, Jobs and Scheduling</a></td></tr><tr><td>Media</td><td>The local <code>public</code> disk</td><td><a href="./../advanced/file-storage.html">File Storage</a></td></tr><tr><td>Resized images</td><td>Resized on every request, sent with a 30-day <code>Cache-Control</code> header</td><td><a href="./../advanced/cache-strategy.html#image-cache">Cache Strategy</a></td></tr></tbody></table><h2 id="tuning-checklist" tabindex="-1">Tuning Checklist <a class="header-anchor" href="#tuning-checklist" aria-label="Permalink to &quot;Tuning Checklist&quot;">​</a></h2><ol><li><strong>Move the queue off <code>sync</code></strong> so mail, index updates and imports leave the request.</li><li><strong>Put the caches and sessions on Redis</strong> when the database is under load, and give the <a href="./configure-fpc.html#choose-where-pages-are-stored">full page cache a store of its own</a>.</li><li><strong><a href="./configure-elasticsearch.html">Use Elasticsearch</a></strong> when database search is too slow for the catalog, and give each environment its own index prefix.</li><li><strong><a href="./../advanced/file-storage.html">Serve media from Amazon S3 or Cloudflare R2</a></strong>, and put a CDN or reverse proxy in front of <code>/cache/</code> so resized images aren&#39;t generated for every visitor.</li></ol><p>Workers, the scheduler and framework caches are part of every deployment; see <a href="./../getting-started/deployment.html#production-checklist">Deployment</a>.</p><h2 id="pages-in-this-section" tabindex="-1">Pages in This Section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in This Section&quot;">​</a></h2><ul><li><strong><a href="./configure-elasticsearch.html">Configure Elasticsearch</a></strong>: connecting a cluster, building the product index, and troubleshooting the connection.</li><li><strong><a href="./configure-fpc.html">Configure Full Page Cache</a></strong>: the switch and lifetime, a store of its own, checking for cache hits, and clearing.</li><li><strong><a href="./configure-varnish.html">Configure Varnish</a></strong>: the separate <code>bagisto/bagisto-varnish</code> package, which replaces the built-in page cache; read its warning about signed-in pages first.</li><li><strong><a href="./configure-laravel-octane.html">Configure Laravel Octane</a></strong>: running Bagisto on FrankenPHP, RoadRunner or Swoole, and the state that outlives a request.</li><li><strong><a href="./configure-load-balancing.html">Configure Load Balancing</a></strong>: what several web servers must share, deploying to them, and an example on AWS.</li></ul><p>Test each change on a staging copy of the store with production-like data before rolling it out. Don&#39;t use a web server page cache such as Nginx&#39;s FastCGI cache; <a href="./configure-fpc.html#things-to-watch">Configure Full Page Cache</a> explains why.</p>',10)]))}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
